}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "片段阅读的核心是\"找主题句\""}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "不要逐字逐句读，要快速定位关键信息"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "干扰项的识别是提高正确率的关键"}]}]}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#eff6ff", "borderColor": "#3b82f6", "icon": "📊"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "刷题建议：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "片段阅读是言语理解的主体。掌握找主题句和排除干扰项两大技巧，正确率可以稳定在75%以上。"}]}]}]}$$ AS jsonb), NULL, '言语理解-片段阅读概述的核心知识点和解题方法。', category_node.id, CAST('["言语理解", "片段阅读概述"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_language_segment_reading", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
